// Generated by deck/tool/shared.mjs from deck/src/house-actions.mjs; do not edit.
// Listed-action ids, labels and service mapping ported from bridge src/act.mjs actionsFor.
// Habitat has entities/states and dispatch; GET /v1/actions is an audit log, not a control catalog.
const labels = {light: 'Lights', switch: 'Switch', fan: 'Fan', input_boolean: 'Toggle', script: 'Script', lock: 'Lock', cover: 'Shades', media_player: 'Media', input_select: 'Mode'};
const list = (value, key) => Array.isArray(value) ? value : value?.[key];
const named = (name, noun, pattern) => pattern.test(name) ? name : `${name} ${noun}`;
// Cover device_class: doors and gates keep their name and ask before opening (a garage door before closing too); the rest are shades.
const doors = {garage: ['Garage door', true], door: ['Door', false], gate: ['Gate', false]};
const shadeLabels = {blind: 'Blinds', curtain: 'Curtains', awning: 'Awning', shutter: 'Shutters', window: 'Window'};

export function habitatActions(entities, states) {
  entities = list(entities, 'entities'); states = list(states, 'states');
  if (!Array.isArray(entities) || !Array.isArray(states)) throw new Error('invalid Habitat entities/states');
  const byId = new Map(states.map(s => [s.entity_id, s]));
  return entities.flatMap(e => {
    const st = byId.get(e.id);
    if (!/^[a-z_]+\.[a-z0-9_]+$/.test(e.id) || !st || ['unknown', 'unavailable'].includes(st.state)) return [];
    const domain = e.id.split('.')[0], state = st.state, base = e.name ?? st.attributes?.friendly_name ?? e.id;
    const one = (verb, title, service, data = {}, confirm = false) => ({id: `${e.id}:${verb}`, title,
      subtitle: [labels[domain], state].filter(Boolean).join(' · '), domain, state, confirm, lastUsed: null,
      entity: e.id, request: {action: `${domain}.${service}`, target: {entity_id: [e.id]}, data}});
    switch (domain) {
      case 'light': return [one('toggle', named(base, 'lights', /light|lamp|chandelier|sconce/i), 'toggle')];
      case 'switch': case 'fan': case 'input_boolean': return [one('toggle', base, 'toggle')];
      case 'script': return [{...one('run', base, 'turn_on'), subtitle: 'Script'}];
      case 'lock': return state === 'locked' ? [one('unlock', `Unlock ${base.toLowerCase()}`, 'unlock', {}, true)] : [one('lock', `Lock ${base.toLowerCase()}`, 'lock')];
      case 'cover': {
        const kind = st.attributes?.device_class, [label, confirmClose] = doors[kind] ?? [shadeLabels[kind] ?? labels.cover, false];
        const name = doors[kind] ? base : named(base, 'shades', /shade|blind|curtain/i), subtitle = `${label} · ${state}`;
        const close = {...one('close', `Close ${name}`, 'close_cover', {}, confirmClose), subtitle}, open = {...one('open', `Open ${name}`, 'open_cover', {}, !!doors[kind]), subtitle};
        return state === 'open' ? [close] : state === 'closed' ? [open] : [close, open];
      }
      case 'media_player': return [one('play_pause', `${base}: play or pause`, 'media_play_pause')];
      case 'input_select': return (st.attributes?.options ?? []).filter(o => o !== state).map(o => ({...one(`set:${o}`, `${base}: ${o}`, 'select_option', {option: o}), subtitle: `${labels[domain]} · now ${state}`}));
      default: return [];
    }
  });
}
